//! C-alignment regression tests (step H1: delete-side B-tree rebalancing). GENERATED by
//! target/perf-work/h1/gen_tests.py: every expected value is what C SQLite 3.54.1 produces for the same statements on
//! the same starting file (page count, free-list length, and for every b-tree page its number, kind and cell count).
//! Starting files that contain index trees or deep trees are images written by C (embedded as hex), so that the tree
//! entering the deletes is the one C has. Each case fails with the delete code of step 5j (it kept leaves until they
//! were empty and rebuilt whole indexes); nothing here depends on files outside the repository.
use crate::Connection;
use sqliters_types::Value;

struct TempDb(std::path::PathBuf);

impl TempDb {
    fn new(name: &str) -> Self {
        let path =
            std::env::temp_dir().join(format!("sqliters-h1-{}-{name}.db", std::process::id()));
        let db = Self(path);
        db.remove_all();
        db
    }
    fn remove_all(&self) {
        for suffix in ["", "-journal", "-wal", "-shm"] {
            let mut s = self.0.clone().into_os_string();
            s.push(suffix);
            let _ = std::fs::remove_file(std::path::PathBuf::from(s));
        }
    }
}

impl Drop for TempDb {
    fn drop(&mut self) {
        self.remove_all();
    }
}

/// Decodes the image notation of the generator: hex digits, `zNNNN` = `0xNNNN` zero bytes.
fn unhex(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let hex = |c: u8| -> u8 {
        match c {
            b'0'..=b'9' => c - b'0',
            _ => c - b'a' + 10,
        }
    };
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'z' {
            let n = b[i + 1..i + 5]
                .iter()
                .fold(0usize, |n, &c| n * 16 + usize::from(hex(c)));
            out.resize(out.len() + n, 0);
            i += 5;
        } else {
            out.push(hex(b[i]) * 16 + hex(b[i + 1]));
            i += 2;
        }
    }
    out
}

fn render(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Integer(i) => i.to_string(),
        Value::Text(s) => s.clone(),
        Value::Blob(b) => String::from_utf8_lossy(b).into_owned(),
        Value::Real(r) => format!("{r}"),
    }
}

/// Writes `image` (or nothing) to a new file, runs `stmts` on it, evaluates `checks` (rows joined
/// with `|`, lines with `\n`) and returns the file together with the check results.
fn run_on(name: &str, image: &[u8], stmts: &[&str], checks: &[&str]) -> (Vec<u8>, Vec<String>) {
    let db = TempDb::new(name);
    if !image.is_empty() {
        std::fs::write(&db.0, image).unwrap();
    }
    let conn = Connection::open(&db.0).unwrap();
    for sql in stmts {
        conn.query(sql, &[])
            .unwrap_or_else(|e| panic!("{sql}: {e:?}"));
    }
    let results = checks
        .iter()
        .map(|sql| {
            conn.query(sql, &[])
                .unwrap_or_else(|e| panic!("{sql}: {e:?}"))
                .rows
                .iter()
                .map(|r| r.values().iter().map(render).collect::<Vec<_>>().join("|"))
                .collect::<Vec<_>>()
                .join("\n")
        })
        .collect();
    assert!(conn.try_close().is_ok());
    (std::fs::read(&db.0).unwrap(), results)
}

fn be16(b: &[u8], i: usize) -> usize {
    usize::from(u16::from_be_bytes([b[i], b[i + 1]]))
}

fn be32(b: &[u8], i: usize) -> u32 {
    u32::from_be_bytes([b[i], b[i + 1], b[i + 2], b[i + 3]])
}

fn page_size(file: &[u8]) -> usize {
    match be16(file, 16) {
        1 => 65_536,
        n => n,
    }
}

fn page_count(file: &[u8]) -> u32 {
    be32(file, 28)
}

fn freelist_count(file: &[u8]) -> u32 {
    be32(file, 36)
}

/// Pre-order walk of the tree rooted at `pgno`: `(page, leaf?, cells)`.
fn walk(file: &[u8], pgno: u32, out: &mut Vec<(u32, bool, u16)>) {
    let ps = page_size(file);
    let page = &file[(pgno as usize - 1) * ps..pgno as usize * ps];
    let hdr = if pgno == 1 { 100 } else { 0 };
    let leaf = page[hdr] & 0x08 != 0;
    let n_cell = be16(page, hdr + 3);
    out.push((pgno, leaf, n_cell as u16));
    if !leaf {
        for i in 0..n_cell {
            let off = be16(page, hdr + 12 + 2 * i);
            walk(file, be32(page, off), out);
        }
        walk(file, be32(page, hdr + 8), out);
    }
}

/// Root pages recorded in `sqlite_schema` (read from the file itself: column 4 of every row).
fn roots(file: &[u8]) -> Vec<u32> {
    fn varint(b: &[u8], mut i: usize) -> (u64, usize) {
        let mut v = 0u64;
        for n in 0..9 {
            let c = b[i];
            i += 1;
            if n == 8 {
                return ((v << 8) | u64::from(c), i);
            }
            v = (v << 7) | u64::from(c & 0x7f);
            if c & 0x80 == 0 {
                break;
            }
        }
        (v, i)
    }
    fn leaves(file: &[u8], pgno: u32, out: &mut Vec<u32>) {
        let ps = page_size(file);
        let page = &file[(pgno as usize - 1) * ps..pgno as usize * ps];
        let hdr = if pgno == 1 { 100 } else { 0 };
        let n_cell = be16(page, hdr + 3);
        if page[hdr] & 0x08 == 0 {
            for i in 0..n_cell {
                leaves(file, be32(page, be16(page, hdr + 12 + 2 * i)), out);
            }
            leaves(file, be32(page, hdr + 8), out);
            return;
        }
        for i in 0..n_cell {
            // payload size, rowid, record header: type, name, tbl_name, rootpage, sql
            let (_, p) = varint(page, be16(page, hdr + 8 + 2 * i));
            let (_, p) = varint(page, p);
            let (hlen, mut h) = varint(page, p);
            let mut body = p + hlen as usize;
            for col in 0..4 {
                let (st, nh) = varint(page, h);
                h = nh;
                let len = match st {
                    0 | 8 | 9 => 0,
                    1..=4 => st as usize,
                    5 => 6,
                    6 | 7 => 8,
                    n => (n as usize - 12) / 2,
                };
                if col == 3 {
                    let v = page[body..body + len]
                        .iter()
                        .fold(0u32, |v, &c| (v << 8) | u32::from(c));
                    let v = if st == 9 { 1 } else { v };
                    if v > 1 {
                        out.push(v);
                    }
                }
                body += len;
            }
        }
    }
    let mut out = vec![1];
    leaves(file, 1, &mut out);
    out.sort_unstable();
    out
}

/// Every b-tree page of the file: trees in root-page order, pages in path order.
fn tree_shape(file: &[u8]) -> Vec<(u32, bool, u16)> {
    let mut out = Vec::new();
    for root in roots(file) {
        walk(file, root, &mut out);
    }
    out
}

/// table tree, 4096-byte pages: leaves more than two thirds free are merged with their siblings (3 -> 2 pages), the root loses its last divider and takes the remaining leaf back (balance-shallower).
#[test]
fn table_leaf_merges_and_root_collapse_4096() {
    let image = Vec::new();
    let stmts: &[&str] = &[
        "CREATE TABLE t(id INTEGER PRIMARY KEY, a TEXT)",
        "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<3000) INSERT INTO t SELECT x, printf('%0100d', x) FROM c",
        "DELETE FROM t WHERE id % 3 <> 0",
        "DELETE FROM t WHERE id BETWEEN 500 AND 2000",
        "DELETE FROM t WHERE id > 2900",
    ];
    let (bytes, results) = run_on(
        "table_leaf_merges_and_root_collapse_4096",
        &image,
        stmts,
        &["SELECT count(*), sum(id) FROM t"],
    );
    assert_eq!(results, ["466|776433"]);
    // C: 84 pages, 65 on the free list; (page, leaf?, cells) of every b-tree page in root / path order.
    assert_eq!(page_count(&bytes), 84, "page count");
    assert_eq!(freelist_count(&bytes), 65, "free-list length");
    let c_shape: &[(u32, bool, u16)] = &[
        (1, true, 1),
        (2, false, 16),
        (3, true, 29),
        (4, true, 31),
        (6, true, 29),
        (9, true, 30),
        (11, true, 29),
        (14, true, 18),
        (16, true, 13),
        (57, true, 31),
        (59, true, 29),
        (62, true, 29),
        (64, true, 30),
        (66, true, 29),
        (69, true, 31),
        (71, true, 29),
        (74, true, 29),
        (76, true, 31),
        (78, true, 19),
    ];
    assert_eq!(
        tree_shape(&bytes),
        c_shape,
        "tree shape differs from the one C produces"
    );
}

