/// auto_vacuum=FULL, rows with overflow pages and an index, written by C: every merge has to move pointer-map entries (children, first overflow pages), commit then relocates pages into the freed slots.
#[test]
fn auto_vacuum_overflow_rows_512() {
    // 41472 bytes written by C for:
    //   PRAGMA page_size=512;
    //   PRAGMA auto_vacuum=1;
    //   CREATE TABLE t(id INTEGER PRIMARY KEY, k TEXT, a BLOB);
    //   CREATE INDEX tk ON t(k);
    //   WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<40) INSERT INTO t SELECT x, printf('%0*d', 30 + (x*31)%200, x), zeroblob((x*7919);
    let image = unhex(
        "",
    );
    let stmts: &[&str] = &[
        "DELETE FROM t WHERE id % 3 = 1",
        "DELETE FROM t WHERE id BETWEEN 12 AND 25",
        "DELETE FROM t WHERE id > 36",
    ];
    let (bytes, results) = run_on(
        "auto_vacuum_overflow_rows_512",
        &image,
        stmts,
        &[
            "SELECT count(*), sum(id), sum(length(k)), sum(length(a)) FROM t",
            "PRAGMA integrity_check",
        ],
    );
    assert_eq!(results, ["15|292|1902|5148", "ok"]);
    // C: 34 pages, 0 on the free list; (page, leaf?, cells) of every b-tree page in root / path order.
    assert_eq!(page_count(&bytes), 34, "page count");
    assert_eq!(freelist_count(&bytes), 0, "free-list length");
    let c_shape: &[(u32, bool, u16)] = &[
        (1, true, 2),
        (3, false, 10),
        (8, true, 3),
        (9, true, 1),
        (17, true, 1),
        (23, true, 3),
        (29, true, 1),
        (11, true, 1),
        (24, true, 1),
        (32, true, 1),
        (27, true, 1),
        (28, true, 1),
        (31, true, 1),
        (4, false, 1),
        (20, true, 9),
        (21, true, 5),
    ];
    assert_eq!(
        tree_shape(&bytes),
        c_shape,
        "tree shape differs from the one C produces"
    );
}

